package checker
import (
 "github.com/microsoft/typescript-go/internal/ast"
 "fmt"
)
var aliasControlWorkers uint64
var moduleCloneControlWorkers uint64
// Scratch observations of actual native operations, not substitute answers.
type AliasControlRow struct { Name string; TargetIdentity string; FirstWorkers, RepeatWorkers uint64; TargetName string; TargetFlags ast.SymbolFlags; Unknown, SameAsRaw, SameAsHead bool; TypeOnlyKind string; OwnMember bool; ImmediateName string; ImmediateSameAsTarget bool; CopyWorkers uint64; RawFieldsCopied, RawUnredirected, ModuleValueOwnerIsClone, ExportTargetRaw bool; OriginatingKind string; ModuleCalls, ModuleConstructs, ModuleIndexes, DirectSourceIndexes, DirectCloneIndexes int }
func (c *Checker) QualifyAliasTargets(file, library *ast.SourceFile, names []string) []AliasControlRow {
 aliases:=map[string]*ast.Symbol{}
 var visit func(*ast.Node)
 visit=func(node *ast.Node) {
  if node.Kind==ast.KindImportEqualsDeclaration || node.Kind==ast.KindNamespaceImport || node.Kind==ast.KindImportSpecifier {
   aliases[node.Name().Text()]=c.getSymbolOfDeclaration(node)
  }
  node.ForEachChild(func(child *ast.Node) bool {visit(child);return false})
 }
 visit(file.AsNode())
 var raw *ast.Symbol
 if library!=nil {raw=c.getSymbolOfDeclaration(library.Statements.Nodes[0])}
 rows:=[]AliasControlRow{}; var head *ast.Symbol
 for _,name:=range names {
  alias:=aliases[name];if alias==nil {panic("missing alias "+name)}
  copiesBefore:=moduleCloneControlWorkers
  before:=aliasControlWorkers;target:=c.resolveAlias(alias);first:=aliasControlWorkers-before
  before=aliasControlWorkers;repeat:=c.resolveAlias(alias);workers:=aliasControlWorkers-before
  if target!=repeat {panic("repeat changes target identity")}
  if name=="Head" {head=target}
  row:=AliasControlRow{Name:name,TargetIdentity:fmt.Sprintf("%p",target),FirstWorkers:first,RepeatWorkers:workers,TargetName:target.Name,TargetFlags:target.Flags,Unknown:target==c.unknownSymbol,SameAsRaw:target==raw,SameAsHead:head!=nil&&target==head}
  if name=="a0" || name=="a1" {
   immediate:=c.getImmediateAliasedSymbol(alias)
   row.ImmediateName=immediate.Name; row.ImmediateSameAsTarget=immediate==target
  }
  if marker:=c.aliasSymbolLinks.Get(alias).typeOnlyDeclaration;marker!=nil {row.TypeOnlyKind=marker.Kind.String()}
  if target!=c.unknownSymbol {row.OwnMember=c.getPropertyOfType(c.getTypeOfSymbol(target),"own")!=nil}
  row.CopyWorkers=moduleCloneControlWorkers-copiesBefore
  if name=="Head" || name=="Twin" {
   row.RawUnredirected=c.getMergedSymbol(raw)==raw
   equal:=func(a,b ast.SymbolTable) bool {if len(a)!=len(b) {return false}; for key,value:=range a {if b[key]!=value{return false}};return true}
   declsEqual:=len(raw.Declarations)==len(target.Declarations)
   if declsEqual {for i,node:=range raw.Declarations {if target.Declarations[i]!=node {declsEqual=false}}}
   row.RawFieldsCopied=declsEqual && target.Flags==raw.Flags|ast.SymbolFlagsTransient && target.ValueDeclaration==raw.ValueDeclaration && target.Parent==raw.Parent && equal(target.Members,raw.Members) && equal(target.Exports,raw.Exports)
   links:=c.exportTypeLinks.Get(target);row.ExportTargetRaw=links.target==raw
   if links.originatingImport!=nil {row.OriginatingKind=links.originatingImport.Kind.String()}
   typ:=c.getTypeOfSymbol(target);row.ModuleValueOwnerIsClone=typ.symbol==target
   members:=c.resolveStructuredTypeMembers(typ)
   row.ModuleCalls=len(members.CallSignatures());row.ModuleConstructs=len(members.ConstructSignatures());row.ModuleIndexes=len(members.indexInfos)
   rawType:=c.getTypeOfSymbol(raw)
   row.DirectSourceIndexes=len(c.resolveStructuredTypeMembers(rawType).indexInfos)
   direct:=c.cloneTypeAsModuleType(raw,rawType,links.originatingImport)
   row.DirectCloneIndexes=len(c.resolveStructuredTypeMembers(c.getTypeOfSymbol(direct)).indexInfos)
  }
  rows=append(rows,row)
 }
 return rows
}

