func runOrder(name,source,library string,names []string,checkedFirst bool) {
 files:=map[string]string{"/main.ts":source,"/tsconfig.json":`{"compilerOptions":{"strict":true,"singleThreaded":true,"noEmit":true,"module":"commonjs","target":"es2020","esModuleInterop":true},"files":["main.ts","lib.ts"]}`,"/lib.ts":library}
 fs:=vfstest.FromMap(files,true);host:=compiler.NewCompilerHost("/",bundled.WrapFS(fs),bundled.LibPath(),nil,nil)
 config,errors:=tsoptions.GetParsedCommandLineOfConfigFile("/tsconfig.json",&core.CompilerOptions{},nil,host,nil);if len(errors)!=0 {panic(errors)}
 program:=compiler.NewProgram(compiler.ProgramOptions{Config:config,Host:host});if errors:=program.GetProgramDiagnostics();len(errors)!=0 {panic(fmt.Sprintf("invalid options/setup: %v",errors))};program.BindSourceFiles()
