 if checkedFirst {c.GetDiagnostics(context.Background(),program.GetSourceFile("/main.ts"))}
 rows:=c.QualifyAliasTargets(program.GetSourceFile("/main.ts"),program.GetSourceFile("/lib.ts"),names)
 for _,row:=range rows {
  if row.RepeatWorkers!=0 {panic("completed repeat executes worker")}
  if row.Name=="Head" || row.Name=="Twin" {if row.CopyWorkers!=func() uint64 {if checkedFirst{return 0};return 1}() || !row.RawFieldsCopied || !row.RawUnredirected || !row.ModuleValueOwnerIsClone || !row.ExportTargetRaw || row.OriginatingKind!="KindImportDeclaration" || row.ModuleCalls!=0 || row.ModuleConstructs!=0 {panic(fmt.Sprintf("module clone fields/publication mismatch: %+v",row))}}
 }
 switch name {
 case "transitive-namespace":
  if rows[0].TargetName!="Target" || rows[0].FirstWorkers!=func() uint64 {if checkedFirst{return 0};return 2}() || rows[1].FirstWorkers!=0 || rows[0].ImmediateName!="a1" || rows[0].ImmediateSameAsTarget || rows[1].ImmediateName!="Target" || !rows[1].ImmediateSameAsTarget {panic("transitive flatten/work mismatch")}
 case "indexed-class-clone":
  if rows[0].DirectSourceIndexes!=1 || rows[0].DirectCloneIndexes!=1 || rows[1].DirectSourceIndexes!=1 || rows[1].DirectCloneIndexes!=1 {panic(fmt.Sprintf("missing indexes: %+v",rows))}
 case "plain-class-clone":
  if rows[0].SameAsRaw || rows[0].Unknown || rows[0].OwnMember || rows[1].SameAsHead || !rows[2].Unknown || !rows[3].Unknown {panic("plain class clone/namespace exclusion mismatch")}
 case "merged-class-clone":
  if rows[0].SameAsRaw || rows[0].Unknown || rows[0].OwnMember || rows[1].SameAsHead || !rows[2].SameAsHead || !rows[3].SameAsHead {panic("merged clone identity/member filtering mismatch")}
 case "type-only-backlink":
  if rows[0].TargetName!="Thing" || rows[0].TypeOnlyKind!="KindExportSpecifier" {panic(fmt.Sprintf("type-only backlink mismatch: %+v", rows[0]))}
 }
 c.GetDiagnostics(context.Background(),program.GetSourceFile("/main.ts"))
 after:=c.QualifyAliasTargets(program.GetSourceFile("/main.ts"),program.GetSourceFile("/lib.ts"),names)
 for i,row:=range after {if row.TargetIdentity!=rows[i].TargetIdentity || row.FirstWorkers!=0 || row.RepeatWorkers!=0 || row.CopyWorkers!=0 {panic(fmt.Sprintf("after-check identity/reuse mismatch: %+v",row))}}
 payload,err:=json.Marshal(map[string]any{"case":name,"checkedFirst":checkedFirst,"rows":rows,"after":after});if err!=nil {panic(err)};fmt.Println(string(payload))
}
func main() {
 run("transitive-namespace","namespace Target { export const value = 17; }\nimport a0 = a1;\nimport a1 = Target;","export {};",[]string{"a0","a1"})
 source:="import * as Head from './lib'; import * as Twin from './lib'; import Tail = Linked; import Linked = Head;"
 run("plain-class-clone",source,"class Foo { static field=11; static own(n:number): string { return 'method'; } } export = Foo;",[]string{"Head","Twin","Linked","Tail"})
 run("indexed-class-clone",source,"declare class Foo { static [key: string]: number | Function; static field: number; static own(n:number): string; } export = Foo;",[]string{"Head","Twin"})
 run("merged-class-clone",source,"class Foo { static field=11; static own(n:number): string { return 'method'; } } namespace Foo { export const merged = 1; } export = Foo;",[]string{"Head","Twin","Linked","Tail"})
 run("type-only-backlink","import { Renamed as Visible } from './lib';","class Thing {} export type { Thing as Renamed };",[]string{"Visible"})
}

