+fn namespace_import_values_retain_distinct_module_symbol_owners() {
+    for checked_first in [false, true] {
+        let arena = Arena::new();
+        let fixture = program(
+            &arena,
+            &[
+                (
+                    "lib",
+                    "class Foo { static field = 11; } namespace Foo { export const merged = 1; } export = Foo;",
+                ),
+                (
+                    "main",
+                    "import * as Head from './lib'; import * as Twin from './lib'; import Raw = require('./lib');",
+                ),
+            ],
+        );
+        let root = fixture.host.files[1].1;
+        let locals = fixture.bound.locals(root).unwrap();
+        let mut checker = Checker::with_module_host(
+            &fixture.bound,
+            &fixture.nodes,
+            &fixture.node_map,
+            Some(&fixture.host),
+        );
+        checker.apply_compiler_options(&tsr_core::CompilerOptions {
+            module: tsr_core::ModuleKind::CommonJS,
+            ..Default::default()
+        });
+        if checked_first {
+            checker.check_source_file(
+                root,
+                tsr_checker::check::FileContext { ambient: false, has_parse_errors: false },
+            );
+        }
+        let head = checker.get_type_of_symbol(locals["Head"]);
+        let twin = checker.get_type_of_symbol(locals["Twin"]);
+        let raw = checker.get_type_of_symbol(locals["Raw"]);
+        let owner = |ty| match &checker.type_of(ty).data {
+            tsr_checker::TypeData::Anonymous { symbol, .. } => symbol.clone(),
+            other => panic!("expected anonymous module value, got {other:?}"),
+        };
+        assert_ne!(owner(head), owner(raw), "a module copy must own its anonymous value");
+        assert_ne!(owner(head), owner(twin), "separate imports need separate cloned symbols");
+        assert_eq!(head, checker.get_type_of_symbol(locals["Head"]));
+        assert_eq!(twin, checker.get_type_of_symbol(locals["Twin"]));
+    }
